import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential

# Initialize Azure Document Intelligence client
endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")
client = DocumentIntelligenceClient(endpoint, AzureKeyCredential(key))

def normalize_expense_fields(document_bytes):
    """
    Normalize extracted expense fields into a standard JSON schema using Azure Document Intelligence.

    Args:
        document_bytes (bytes): The raw bytes of the expense document (PDF or image).

    Returns:
        dict: A standardized JSON schema containing the extracted expense fields.
    """
    # Use the prebuilt invoice model
    invoice_model_id = "prebuilt-invoice"

    # Analyze the document using Azure Document Intelligence
    poller = client.begin_analyze_document(invoice_model_id, document_bytes)
    result = poller.result()

    # Initialize the standardized JSON schema
    standardized_data = {
        "invoice_number": None,
        "date": None,
        "total_amount": None,
        "vendor": {
            "name": None,
            "address": None
        },
        "customer": {
            "name": None,
            "address": None
        },
        "lines": []
    }

    # Extract fields from the analysis result
    for doc in result.documents:
        for field in doc.fields:
            if field.name == "InvoiceId":
                if field.value:
                    standardized_data["invoice_number"] = field.value
            elif field.name == "InvoiceDate":
                if field.value:
                    standardized_data["date"] = field.value
            elif field.name == "TotalAmount":
                if field.value:
                    standardized_data["total_amount"] = field.value
            elif field.name == "Vendor":
                if field.value:
                    for vendor_field in field.value.fields:
                        if vendor_field.name == "Name":
                            if vendor_field.value:
                                standardized_data["vendor"]["name"] = vendor_field.value
                        elif vendor_field.name == "Address":
                            if vendor_field.value:
                                standardized_data["vendor"]["address"] = vendor_field.value
            elif field.name == "Customer":
                if field.value:
                    for customer_field in field.value.fields:
                        if customer_field.name == "Name":
                            if customer_field.value:
                                standardized_data["customer"]["name"] = customer_field.value
                        elif customer_field.name == "Address":
                            if customer_field.value:
                                standardized_data["customer"]["address"] = customer_field.value
            elif field.name == "Items":
                if field.value:
                    for item_field in field.value.list:
                        line_item = {
                            "description": None,
                            "quantity": None,
                            "unit_price": None,
                            "amount": None
                        }
                        for item_subfield in item_field.fields:
                            if item_subfield.name == "Description":
                                if item_subfield.value:
                                    line_item["description"] = item_subfield.value
                            elif item_subfield.name == "Quantity":
                                if item_subfield.value:
                                    line_item["quantity"] = item_subfield.value
                            elif item_subfield.name == "UnitPrice":
                                if item_subfield.value:
                                    line_item["unit_price"] = item_subfield.value
                            elif item_subfield.name == "Amount":
                                if item_subfield.value:
                                    line_item["amount"] = item_subfield.value
                        standardized_data["lines"].append(line_item)

    return standardized_data
